import pickle
import os
import numpy as np

# Directory containing the .pkl files
directory = "/tmp/unzipped_inputs/inputs"

# Function to analyze a single .pkl file
def analyze_file(file_path):
    with open(file_path, 'rb') as f:
        data = pickle.load(f)

    file_info = {
        "file": file_path,
        "type": type(data),
        "details": {}
    }

    if isinstance(data, np.ndarray):
        file_info["details"] = {
            "shape": data.shape,
            "dtype": data.dtype
        }
    elif isinstance(data, list):
        file_info["details"] = {
            "length": len(data),
            "sample_content": data[:3]  # Show the first 3 elements
        }
    elif isinstance(data, dict):
        file_info["details"] = {
            "keys": list(data.keys()),
            "sample_values": {k: data[k] for k in list(data.keys())[:3]}  # First 3 keys and values
        }
    else:
        file_info["details"] = str(data)

    return file_info

# Process all .pkl files in the directory
results = []
for file in os.listdir(directory):
    file_path = os.path.join(directory, file)
    if file.endswith('.pkl'):
        results.append(analyze_file(file_path))

# Output results
output_file = "/tmp/pkl_analysis_output.txt"
with open(output_file, "w") as f:
    for result in results:
        f.write(f"File: {result['file']}\n")
        f.write(f"Type: {result['type']}\n")
        f.write(f"Details: {result['details']}\n")
        f.write("\n\n")

print(f"Analysis complete. Results saved to {output_file}")

